const r=await fetch('http://127.0.0.1:17448/api/supervisor-watchdog/managed-chats?inspect=1');
const j=await r.json();
const cid='6abda64b-aac4-83eb-adee-dc7143ca5d2b';
const conv=v=>{try{const u=new URL(String(v||''));const p=u.pathname.split('/').filter(Boolean);if(p.length===2&&p[0]==='c')return p[1];if(p.length===4&&p[0]==='g'&&p[2]==='c')return p[3]}catch{}return ''};
const rows=(j.chats||[]).filter(x=>conv(x.url)===cid).map(x=>({
 id:x.id,name:x.name,url:x.url,projectId:x.projectId,profileId:x.profileId,
 repository:x.repository,branch:x.branch,gitHead:x.gitHead,status:x.status,
 contextLimit:x.contextLimit,highMode:x.highMode,openTabs:x.openTabs,
 rotateWithProject:x.rotateWithProject,enabled:x.enabled,lastSeenAt:x.lastSeenAt
}));
process.stdout.write(JSON.stringify({http:r.status,count:rows.length,rows}));

